<?php $pageTitle='Assignments';$subtitle='Assign internal work and delivery jobs to field employees.';$active='Assignments';require __DIR__.'/_layout.php';$pdo=db();$emps=$pdo->query("SELECT id,name FROM users WHERE role='employee' AND status='active' ORDER BY name")->fetchAll();$orders=$pdo->query("SELECT id,order_number,customer_name,address_line1,city,state,pincode FROM orders WHERE order_status NOT IN ('cancelled','delivered') ORDER BY created_at DESC LIMIT 100")->fetchAll();$rows=$pdo->query("SELECT ea.*,u.name employee_name,o.order_number FROM employee_assignments ea JOIN users u ON u.id=ea.employee_id LEFT JOIN orders o ON o.id=ea.order_id ORDER BY ea.created_at DESC LIMIT 100")->fetchAll();?><div class="card"><form id="assignForm"><div class="form-grid"><div class="field"><label>Employee</label><select class="select" name="employee_id" required><option value="">Select employee</option><?php foreach($emps as $e):?><option value="<?=$e['id']?>"><?=ae($e['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Type</label><select class="select" name="assignment_type"><option value="work">Work</option><option value="delivery">Delivery</option></select></div><div class="field"><label>Priority</label><select class="select" name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></div><div class="field"><label>Due At</label><input class="input" name="due_at" type="datetime-local"></div><div class="field full"><label>Order (optional for delivery)</label><select class="select" name="order_id"><option value="">No linked order</option><?php foreach($orders as $o):?><option value="<?=$o['id']?>"><?=ae($o['order_number'].' — '.$o['customer_name'].' — '.$o['city'])?></option><?php endforeach;?></select></div><div class="field full"><label>Title</label><input class="input" name="title" required placeholder="Delivery / installation / customer visit"></div><div class="field"><label>Description</label><textarea class="textarea" name="description" rows="4"></textarea></div><div class="field"><label>Address</label><textarea class="textarea" name="address" rows="4"></textarea></div></div><button class="btn primary" style="margin-top:15px">Assign Work</button></form></div><div class="card" style="margin-top:18px"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Type</th><th>Title</th><th>Order</th><th>Priority</th><th>Status</th><th>Due</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=ae($r['employee_name'])?></td><td><span class="pill blue"><?=ae($r['assignment_type'])?></span></td><td><strong><?=ae($r['title'])?></strong><br><small><?=ae($r['description'])?></small></td><td><?=ae($r['order_number']??'—')?></td><td><?=ae($r['priority'])?></td><td><span class="pill <?=in_array($r['status'],['completed'])?'green':'gold'?>"><?=ae($r['status'])?></span></td><td><?=ae($r['due_at']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><script>document.querySelector('#assignForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','assign');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)})</script><?php require __DIR__.'/_foot.php'; ?>
